// Normalize the merged trigger event (created OR updated) into a single record.
// Deterministic; no LLM. Also decides whether the TRIGGER event itself should
// even raise a conflict (status/transparency/declined/all-day gating).
// Convergence-safe: guard the $() ref in try/catch.
function firstFrom(nodeName) {
  try { return $(nodeName).first().json; } catch (e) { return null; }
}
// The merged input carries the triggering event on $input; use it directly,
// with the two trigger nodes as defensive fallbacks.
let trig = {};
try { trig = $input.item.json || {}; } catch (e) { trig = {}; }
if (!trig || !trig.start) {
  trig = firstFrom('Calendar Event Created') || firstFrom('Calendar Event Updated') || trig || {};
}

const SELF_EMAIL = 'alex@ahbadvisors.com';

// All-day events have start.date (no dateTime). An all-day OOO / travel block
// should NOT raise a conflict against every meeting that day, so we SKIP
// all-day trigger events entirely (decision: skip; commented here).
const isAllDayTrigger = Boolean(trig.start && trig.start.date && !trig.start.dateTime);

// The invitee's own responseStatus on the trigger event: if Alex declined it,
// it should not raise a conflict.
let selfDeclined = false;
try {
  const atts = Array.isArray(trig.attendees) ? trig.attendees : [];
  const me = atts.find(a => a && (a.self === true || (a.email || '').toLowerCase() === SELF_EMAIL.toLowerCase()));
  if (me && me.responseStatus === 'declined') selfDeclined = true;
} catch (e) { selfDeclined = false; }

// Trigger-level status / transparency gating.
const trigCancelled = trig.status === 'cancelled';
const trigTransparent = trig.transparency === 'transparent';

// The trigger event should be processed only if it is a real, opaque,
// non-declined, timed (non-all-day) event.
const processTrigger = !isAllDayTrigger && !trigCancelled && !trigTransparent && !selfDeclined;

const startRaw = (trig.start && (trig.start.dateTime || trig.start.date)) || '';
const endRaw = (trig.end && (trig.end.dateTime || trig.end.date)) || '';

return {
  json: {
    trigId: trig.id || '',
    trigTitle: trig.summary || '(no title)',
    trigStartRaw: startRaw,
    trigEndRaw: endRaw,
    processTrigger,
    skipReason: isAllDayTrigger ? 'all-day' : (trigCancelled ? 'cancelled' : (trigTransparent ? 'transparent' : (selfDeclined ? 'declined' : '')))
  }
};

// Deterministic overlap detection — NO LLM.
// Reads the normalized trigger event and the getAll window of existing events,
// then keeps only TRUE overlaps, excluding self, cancelled/transparent/declined
// events, and Reclaim/decompress/task-detail noise.
//
// FIXES vs Relay (flow had 0 runs, never fired):
//   1. Self-exclusion by ID: Relay used `Event ID equal trigger.Event ID` which,
//      combined with `Title notEqual`, could NEVER match. We exclude self via
//      existing.id !== trigger.id (the intended notEqual).
//   2. Reclaim/noise skip migrated from OR-of-notContains (near-always true) to AND
//      (every clause must hold) so the filter actually removes those events.
//   3. Relay's dead empty `#each` loop is replaced by a computed markdown string
//      that the ClickUp node commits verbatim.
//
// 2d UPGRADES (this pass):
//   - eventUpdated trigger feeds the same path (reschedule awareness).
//   - Event-status filtering: skip existing events that are cancelled,
//     transparency==='transparent' (marked free), or where the invitee's own
//     responseStatus==='declined'.
//   - Embeds a stable machine key `[gcal:<trigId>]` in the task name so the
//     dedup lookup can find an existing conflict task without a custom field.

// --- Trigger event (from Normalize Trigger; wrapped defensively) ---
function safeCtx() {
  try { return $('Normalize Trigger').item.json || {}; }
  catch (e) { return {}; }
}
const ctx = safeCtx();

const SELF_EMAIL = 'alex@ahbadvisors.com';
const trigStart = new Date(ctx.trigStartRaw || 0).getTime();
const trigEnd = new Date(ctx.trigEndRaw || 0).getTime();
const trigId = ctx.trigId || '';
const trigTitle = ctx.trigTitle || '(no title)';

// Human-readable start for the task name, e.g. "Mon, Jul 20 at 2:00 PM".
function fmt(dt) {
  try {
    return new Date(dt).toLocaleString('en-US', {
      weekday: 'short', month: 'short', day: 'numeric',
      hour: 'numeric', minute: '2-digit', hour12: true
    });
  } catch (e) { return String(dt || ''); }
}
const trigStartFmt = fmt(trigStart);

// Noise filters (migrated as AND — an event survives only if NONE of these hit).
const RECLAIM_A = 'This AI-powered event was created by Reclaim.ai';
const RECLAIM_B = 'This event was created by Reclaim';
const TASK_DETAIL = "Only you can see this Task's event details. It will show as busy to others and automatically reschedule if booked over.";

const conflicts = [];
for (const item of $input.all()) {
  const ev = item.json || {};
  const id = ev.id || '';
  const title = ev.summary || '(no title)';
  const desc = ev.description || '';
  const evStart = new Date((ev.start && (ev.start.dateTime || ev.start.date)) || 0).getTime();
  const evEnd = new Date((ev.end && (ev.end.dateTime || ev.end.date)) || 0).getTime();

  // True overlap: existing.start < trigger.end AND existing.end > trigger.start.
  if (!(evStart < trigEnd && evEnd > trigStart)) continue;
  // Exclude self by ID (the fix for the equal->notEqual bug).
  if (id && trigId && id === trigId) continue;

  // Event-status filtering (2d upgrade): a cancelled, free-marked, or
  // Alex-declined existing event is not a real conflict.
  if (ev.status === 'cancelled') continue;
  if (ev.transparency === 'transparent') continue;
  let evDeclined = false;
  try {
    const atts = Array.isArray(ev.attendees) ? ev.attendees : [];
    const me = atts.find(a => a && (a.self === true || (a.email || '').toLowerCase() === SELF_EMAIL.toLowerCase()));
    if (me && me.responseStatus === 'declined') evDeclined = true;
  } catch (e) { evDeclined = false; }
  if (evDeclined) continue;

  // Exclude Reclaim / decompress / task-detail noise (AND of notContains).
  if (desc.includes(RECLAIM_A)) continue;
  if (desc.includes(RECLAIM_B)) continue;
  if (desc.includes(TASK_DETAIL)) continue;
  if (title.toLowerCase().includes('decompress')) continue;

  const creatorName = (ev.creator && (ev.creator.displayName || ev.creator.email)) || '';
  const creatorEmail = (ev.creator && ev.creator.email) || '';
  conflicts.push({
    title,
    start: (ev.start && (ev.start.dateTime || ev.start.date)) || '',
    end: (ev.end && (ev.end.dateTime || ev.end.date)) || '',
    startFmt: fmt((ev.start && (ev.start.dateTime || ev.start.date)) || ''),
    endFmt: fmt((ev.end && (ev.end.dateTime || ev.end.date)) || ''),
    creatorName,
    creatorEmail
  });
}

// Stable machine key embedded in the task NAME for dedup (no custom field on the
// Scheduling Conflicts list). Downstream lookup matches on this token.
const gcalKey = `[gcal:${trigId}]`;

// Build the ClickUp description string (replaces Relay's dead #each loop).
const lines = conflicts.map(c => {
  const who = c.creatorName ? ` - ${c.creatorName}${c.creatorEmail ? ' (' + c.creatorEmail + ')' : ''}` : '';
  return `- ${c.title} [${c.startFmt} - ${c.endFmt}]${who}`;
});
const taskDescription =
  `Conflict detected for event: **${trigTitle}** at ${trigStartFmt}.\n\n` +
  `**Conflicting events:**\n` +
  (lines.length ? lines.join('\n') : '- (none)') +
  `\n\n_key: ${gcalKey}_`;

// Build the Slack summary (bullet list).
const slackLines = conflicts.map(c => `\u2022 ${c.title} (${c.startFmt} - ${c.endFmt})`);
const slackSummary =
  `:calendar: Scheduling conflict detected for event: *${trigTitle}*\n` +
  `Time: ${trigStartFmt}\n\n` +
  `Conflicts with:\n` +
  (slackLines.length ? slackLines.join('\n') : '\u2022 (none)');

// dueDate = event start minus 2 days (epoch ms), for the ClickUp task.
const dueDateMs = trigStart ? trigStart - 2 * 24 * 60 * 60 * 1000 : '';

return [{
  json: {
    conflictCount: conflicts.length,
    conflicts,
    trigId,
    gcalKey,
    triggerTitle: trigTitle,
    triggerStartFmt: trigStartFmt,
    taskName: `Scheduling conflict for event: ${trigTitle} on ${trigStartFmt} ${gcalKey}`,
    taskDescription,
    slackSummary,
    dueDateMs
  }
}];

// Parse the ClickUp list-task lookup response and dedup on the gCal key
// embedded in the task NAME (no custom field on the Scheduling Conflicts list).
// Deterministic; no LLM. Convergence-safe: guard the upstream $() ref.
// The GET returns { tasks: [...] }. We treat the FIRST OPEN task whose name
// contains `[gcal:<trigId>]` as the existing conflict task for this event.
let ctx = {};
try { ctx = $('Compute Conflicts').item.json || {}; } catch (e) { ctx = {}; }

let resp = {};
try { resp = $input.item.json || {}; } catch (e) { resp = {}; }

let tasks = [];
if (Array.isArray(resp.tasks)) tasks = resp.tasks;
else if (resp.body && Array.isArray(resp.body.tasks)) tasks = resp.body.tasks;

const key = ctx.gcalKey || '';
let existingTaskId = '';
if (key) {
  const match = tasks.find(t => t && typeof t.name === 'string' && t.name.includes(key));
  if (match) existingTaskId = match.id || '';
}
const found = Boolean(existingTaskId);

return {
  json: Object.assign({}, ctx, {
    found,
    existingTaskId
  })
};
